DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.validate_club_form()'::regprocedure) INTO definition; definition:=replace(definition,'jsonb_array_elements(NEW.fields) f WHERE f->>''type''','jsonb_array_elements(NEW.fields) AS element(value) WHERE element.value->>''type'''); EXECUTE definition; SELECT pg_get_functiondef('public.submit_club_form(uuid,integer,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'jsonb_array_elements(frm.fields) f WHERE f->>''id''=key AND f->>''type''','jsonb_array_elements(frm.fields) AS element(value) WHERE element.value->>''id''=key AND element.value->>''type'''); EXECUTE definition; END; $$;